    /// How many kinds the registry has.
    pub const COUNT: usize = 1506;

    /// The kind with this protocol id, or `Unknown`.
    pub fn from_id(id: u32) -> Self {
        usize::try_from(id)
            .ok()
            .and_then(|i| ITEM_KINDS.get(i))
            .copied()
            .unwrap_or(Self::Unknown(id))
    }

